mapper.select:
SELECT sd.id, sd.name, sd.version, sd.params_json, sd.enabled, sd.created_at
FROM strategy_definition sd
WHERE sd.id = #{strategy_id}

SELECT ss.asof_date, ss.score, ss.recommendation, ss.features_json, ss.data_quality
FROM signal_snapshot ss
WHERE ss.strategy_id = #{strategy_id}
ORDER BY ss.asof_date DESC
LIMIT #{limit}

mapper.update:
UPDATE strategy_definition
SET name = #{name},
    version = #{version},
    params_json = #{params_json},
    enabled = #{enabled}
WHERE id = #{id}
